/**
 * Lightweight HTML→Markdown conversion shared by the file exports and the
 * Obsidian integration. Regex-based: notule HTML is generated by us and uses a
 * small, known tag set, but the styled profiles wrap it in `<style>` + semantic
 * `<div>`s (kicker, sections, decision callouts, badge chips), so those are
 * flattened to clean Markdown here.
 */
export function htmlToMarkdown(html: string): string {
  let md = html;

  // 1. Drop non-content blocks — otherwise the CSS in <style> leaks as text.
  md = md.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "");
  md = md.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "");
  md = md.replace(/<head[^>]*>[\s\S]*?<\/head>/gi, "");
  md = md.replace(/<!--[\s\S]*?-->/g, "");
  // Drop the "Vergaderverslag" kicker label.
  md = md.replace(/<div[^>]*class="[^"]*kicker[^"]*"[^>]*>[\s\S]*?<\/div>/gi, "");

  // 2. Badge/meta chips → inline so they stay on the same line as their item.
  //    Other </span> become a space so adjacent inline spans (e.g. the Datum/Type
  //    meta) don't glue together.
  md = md.replace(/<span[^>]*class="[^"]*badge[^"]*"[^>]*>([\s\S]*?)<\/span>/gi, " — $1");
  md = md.replace(/<\/span>/gi, " ");

  // 3. Headings.
  md = md.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, "\n# $1\n");
  md = md.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, "\n## $1\n");
  md = md.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, "\n### $1\n");
  md = md.replace(/<h4[^>]*>([\s\S]*?)<\/h4>/gi, "\n#### $1\n");

  // 4. Inline emphasis.
  md = md.replace(/<(strong|b)[^>]*>([\s\S]*?)<\/\1>/gi, "**$2**");
  md = md.replace(/<(em|i)[^>]*>([\s\S]*?)<\/\1>/gi, "*$2*");

  // 5. List items, line breaks, paragraphs, quotes.
  md = md.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, "\n- $1");
  md = md.replace(/<br\s*\/?>/gi, "\n");
  md = md.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, "\n$1\n");
  md = md.replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi, "\n> $1\n");

  // 6. Block containers → newline so adjacent sections don't run together.
  md = md.replace(/<\/?(?:div|section|ul|ol|table|thead|tbody|tr)[^>]*>/gi, "\n");

  // 7. Strip any remaining tags.
  md = md.replace(/<[^>]+>/g, "");

  // 8. Decode entities.
  md = md
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&nbsp;/g, " ")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");

  // 9. Trim each line, collapse blank runs.
  md = md
    .split("\n")
    .map((line) => line.trim())
    .join("\n");
  md = md.replace(/\n{3,}/g, "\n\n");
  return md.trim();
}
